3	namespace App\Console\Commands;
4	
5	use Barryvdh\DomPDF\Facade\Pdf;
6	use Illuminate\Console\Command;
7	use App\Models\TaxReturn\TaxYear;
8	use Illuminate\Support\HtmlString;
9	use Illuminate\Support\Facades\File;
10	use App\Models\TaxReturn\Contributor;
11	use Illuminate\Support\Facades\Storage;
12	
13	class CreateTaxReport extends Command
14	{
15	    /**
16	     * The name and signature of the console command.
17	     * artisan tax:make-report FRNMNL82S24C957A 2024
18	     *
19	     * @var string
20	     */
21	    protected $signature = 'tax:make-report 
22	        {code : tax code of the contributor}
23	        {year : year of presentation, not tax year}
24	    ';
25	
26	    /**
27	     * The console command description.
28	     *
29	     * @var string
30	     */
31	    protected $description = 'Command description';
32	
33	    /**
34	     * Execute the console command.
35	     */
36	    public function handle(): void
37	    {
38	        // get the contributor
39	        $code = strtoupper($this->argument('code'));
40	        $contributor = Contributor::where('tax_code', $code)->firstOrFail();
41	
42	        // get the year
43	        $year = $this->argument('year');
44	        $taxYear = TaxYear::where([['year', $year], ['tax_contributor_id', $contributor->id]])->firstOrFail();
45	
46	        // get all the documents
47	        $documents = $taxYear->documents()->orderBy('id')->get();
48	
49	        // filename
50	        $directory = storage_path('app/tax-reports/'.$contributor->tax_code.'/'. $taxYear->year.'/'.uniqid());
51	        File::ensureDirectoryExists($directory, 0755, true);
52	
53	
54	        // create document files in the directory
55	        $globalKey = 0;
56	        $outputDocuments = [];
57	        foreach ($documents as $document) {
58	            $globalKey++;
59	            $outputDocuments[$document->id] = [];
60	
61	            $documentPad = str_pad((string)$globalKey, 3, '0', STR_PAD_LEFT);
62	
63	            foreach ($document->files as $k => $file) {
64	                $source = Storage::disk('public')->path($file);
65	                $filename = pathinfo($file, PATHINFO_BASENAME);
66	
67	                $path = $directory.'/'.$documentPad.'-'.$document->slugForFile($filename, $k === 0 ? '' : '-'.$k);
68	
69	                $outputDocuments[$document->id][] = $path;
70	
71	                File::copy($source, $path);
72	            }
73	        }
74	
75	        // data for pdf
76	        $data = [
77	            'title' => new HtmlString(
78	                'Dichiarazione '
79	                .$taxYear->year
80	                .' / redditi anno '.$taxYear->tax_year
81	                ."<br>"
82	                . $contributor->firstname.' '.$contributor->lastname
83	                . ' / '.$contributor->tax_code
84	            ),
85	            'intro' => new HtmlString(nl2br($taxYear->notes)),
86	            'documents' => $documents,
87	            'outputDocuments' => $outputDocuments,
88	            'directory' => $directory,
89	        ];
90	
91	        // create report
92	        $pdf = Pdf::loadView('tax-report.template', $data)
93	            ->setOption([
94	                'defaultFont' => 'sans-serif'
95	            ])
96	            ->save($directory.'/'.str_pad('0', 3, '0', STR_PAD_LEFT).'-elenco-documenti.pdf');
97	
98	
99	        // create a zip of the folder
100	        $zip = new \ZipArchive();
101	        $zipFilename = $directory.'/'.$contributor->tax_code.'-'.$taxYear->year.'.zip';
102	        if ($zip->open($zipFilename, \ZipArchive::CREATE) === true) {
103	            $files = new \RecursiveIteratorIterator(
104	                new \RecursiveDirectoryIterator($directory),
105	                \RecursiveIteratorIterator::LEAVES_ONLY
106	            );
107	
108	            foreach ($files as $name => $file) {
109	                if (!$file->isDir()) {
110	                    $filePath = $file->getRealPath();
111	                    $relativePath = substr($filePath, strlen($directory) + 1);
112	                    $zip->addFile($filePath, $relativePath);
113	                }
114	            }
115	            $zip->close();
116	        }
117	
118	
119	
120	
121	    }
122	}
